function render_argument_figures()
root=fileparts(fileparts(fileparts(fileparts(mfilename('fullpath')))));out=fullfile(root,'06-figure','corrected-20260912');figdir=fullfile(out,'figures');prev=fullfile(out,'previews');if ~isfolder(figdir),mkdir(figdir);end;if ~isfolder(prev),mkdir(prev);end
domain_figure(figdir,prev);hierarchy_figure(figdir,prev);data_figure(root,figdir,prev);moving_figure(figdir,prev);workflow_figure(figdir,prev);fprintf('CORRECTED_ARGUMENT_FIGURES_PASS 5\n');
end
function textbook_schematic(fd,pd)
f=figure('Visible','off','Color','w','InvertHardcopy','off','Units','centimeters','Position',[2 2 16.6 8.8]);ax=axes(f,'Position',[.04 .08 .92 .84]);axis(ax,[0 1 0 1]);axis(ax,'off');hold(ax,'on');
% paired textbook-style states: fixed reference and shrinking moving domain
rectangle(ax,'Position',[.08 .26 .22 .48],'Curvature',[.08 .08],'EdgeColor',[.15 .15 .15],'LineWidth',1.1);plot(ax,[.08 .30],[.50 .50],':','Color',[.35 .35 .35]);plot(ax,[.19 .19],[.26 .74],':','Color',[.35 .35 .35]);text(ax,.19,.80,'初始/参考状态','HorizontalAlignment','center','FontWeight','bold');text(ax,.19,.20,'R(0)=2 cm','HorizontalAlignment','center');text(ax,.205,.57,'z','FontSize',9);text(ax,.28,.53,'r','FontSize',9);annotation(f,'arrow',[.19 .19],[.50 .70],'Color',[.15 .15 .15]);annotation(f,'arrow',[.19 .27],[.50 .50],'Color',[.15 .15 .15]);
rectangle(ax,'Position',[.39 .32 .16 .36],'Curvature',[.08 .08],'EdgeColor',[.15 .15 .15],'LineWidth',1.1);plot(ax,[.39 .55],[.50 .50],':','Color',[.35 .35 .35]);plot(ax,[.47 .47],[.32 .68],':','Color',[.35 .35 .35]);text(ax,.47,.80,'收缩/移动状态','HorizontalAlignment','center','FontWeight','bold');text(ax,.47,.24,'R(t)<R(0)','HorizontalAlignment','center');text(ax,.57,.50,'移动边界','VerticalAlignment','middle');annotation(f,'arrow',[.33 .39],[.50 .50],'Color',[.15 .15 .15]);
% flux/interaction panel
plot(ax,[.75 .75],[.20 .78],'Color',[.15 .15 .15],'LineWidth',1.1);plot(ax,[.68 .82],[.78 .78],'Color',[.15 .15 .15]);plot(ax,[.68 .82],[.20 .20],'Color',[.15 .15 .15]);text(ax,.75,.84,'轴向剖面与边界交换','HorizontalAlignment','center','FontWeight','bold');annotation(f,'arrow',[.62 .72],[.63 .63],'Color',[.15 .15 .15]);text(ax,.64,.66,'q_T','HorizontalAlignment','center');annotation(f,'arrow',[.88 .78],[.51 .51],'Color',[.15 .15 .15]);text(ax,.88,.55,'q_m','HorizontalAlignment','center');annotation(f,'arrow',[.78 .78],[.76 .65],'Color',[.15 .15 .15]);text(ax,.80,.71,'−∂T/∂r','FontSize',8);annotation(f,'arrow',[.78 .78],[.25 .36],'Color',[.15 .15 .15]);text(ax,.80,.30,'−∂C/∂r','FontSize',8);text(ax,.5,.07,'图示采用轴对称坐标；外边界施加热/湿 Robin 交换，Q4 额外引入 R(t) 与 Jacobian 守恒修正。','HorizontalAlignment','center','FontSize',8);savefigs(f,'FIG-MODEL-SCHEMATIC-TEXTBOOK',fd,pd);
end
