function domain_figure(fd,pd)
[f,ax]=canvas();rectangle(ax,'Position',[.06 .18 .32 .62],'Curvature',[.08 .08],'FaceColor',[.94 .97 1],'EdgeColor',[0 .35 .65],'LineWidth',1.5);plot(ax,[.06 .38],[.49 .49],'--','Color',[.4 .4 .4]);plot(ax,[.22 .22],[.18 .80],':','Color',[.4 .4 .4]);text(ax,.22,.84,'二维轴对称计算域','HorizontalAlignment','center','FontWeight','bold');text(ax,.22,.14,'r=0 轴线：零通量','HorizontalAlignment','center');text(ax,.49,.45,'r=R(t)：Robin 换热/换湿','HorizontalAlignment','center','FontSize',7.5);annotation(f,'arrow',[.38 .49],[.51 .51],'Color',[.84 .37 0]);annotation(f,'arrow',[.22 .22],[.49 .76],'Color',[0 .45 .70]);text(ax,.24,.72,'z');annotation(f,'arrow',[.22 .35],[.49 .49],'Color',[0 .45 .70]);text(ax,.33,.52,'r');
rectangle(ax,'Position',[.61 .22 .23 .55],'Curvature',[.08 .08],'FaceColor',[1 .97 .91],'EdgeColor',[.84 .37 0],'LineWidth',1.5);text(ax,.725,.81,'Q4 收缩域','HorizontalAlignment','center','FontWeight','bold');plot(ax,[.655 .655],[.22 .77],'--','Color',[.84 .37 0]);annotation(f,'arrow',[.77 .70],[.51 .51],'Color',[.84 .37 0]);text(ax,.725,.47,'R(t)↓','HorizontalAlignment','center');text(ax,.725,.16,'移动边界保持干固体连续性','HorizontalAlignment','center');text(ax,.5,.94,'圆柱药材的坐标、边界条件与热湿传递','HorizontalAlignment','center','FontSize',11,'FontWeight','bold');savefigs(f,'FIG-MODEL-DOMAIN',fd,pd);
